    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint _val1, uint _val2) public {
        require(_val1 != _val2);

        bool firstReverted;
        c.SetMinSum(_val1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        uint afterFirst = c.MinSum(); if (__ESBMC_reverted()) return;

        bool secondReverted;
        c.SetMinSum(_val2); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        uint afterSecond = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(!firstReverted && !secondReverted && afterFirst == _val1 && afterSecond == _val2);
    }
